}

/* ★2. UI 全局深度重构 */
* {
    border-radius: 0 !important;
}

.text_pole,
textarea,
select,
.menu_button,
.character_select,
.group_select,
input[type="text"],
input[type="number"] {
    background-color: #FAFAFA !important;
    border: 1px solid #B5B2BB !important;
    color: #2C2A30 !important;
    border-radius: 0 !important;
    box-shadow: 2px 2px 0 rgba(44, 42, 48, .05) !important;
    transition: all .2s ease;
}

.text_pole:focus,
textarea:focus,
select:focus {
