    color: #1a1a1a !important;
}

.inline-drawer-toggle i,
.inline-drawer-toggle .fa-chevron-down,
.inline-drawer-toggle .fa-chevron-right,
.inline-drawer-icon {
    color: #C8D7B4 !important;
    text-shadow: none !important;
}

#right-nav h4,
#left-nav h4,
.inline-drawer-header h4,
.standoutHeader,
.drawer-content h4 {
