    width: 34px !important;
    height: 24px !important;
    background: url('https://i.postimg.cc/fWgJ7Kcp/IMG-1808.png') center/contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: drop-shadow(1px 1px 0 rgba(44, 42, 48, .2)) grayscale(.8) !important;
}

input[type="checkbox"] {
    border-radius: 0 !important;
    -webkit-appearance: none;
    appearance: none;
    background: 0 0 !important;
    border: 1px solid #B5B2BB !important;
    width: 16px;
    height: 16px;
    position: relative;
    vertical-align: middle;
    cursor: pointer;
    outline: none !important;
}

input[type="checkbox"]:checked {
    border-color: #C8D7B4 !important;
    background: 0 0 !important;
}

input[type="checkbox"]::before {
    content: none !important;
}

input[type="checkbox"]:checked::after {
    content: '' !important;
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%) !important;
    width: 14px;
    height: 14px;
    background: url('https://i.postimg.cc/Ghm7sccV/IMG-1812.jpg') center/cover no-repeat !important;
    filter: contrast(1.2) !important;
}

::-webkit-scrollbar {
    display: none;
}

#top-bar {
    margin: 0 auto;
    left: 0;
    right: 0;
    display: inline-block;
    height: 24px;
    position: absolute;
    box-shadow: none;
    opacity: 0;
    z-index: 3005;
}

.drawer-icon {
    transform: scale(.55);
    color: #E3E9D7;
}

#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
